.pill--paid, .pill--approved, .pill--active { color: var(--color-ok); background: #e6f5ec; }
.pill--pending_approval, .pill--paused { color: var(--color-warning); background: var(--color-warning-bg); }
.pill--rejected { color: var(--color-danger); background: var(--color-danger-bg); }
